import React from 'react';
import logoNuevo from '../assets/img/logonuevo.png';

// Brasas flotantes (deterministas, sin Math.random para render estable)
const EMBERS = Array.from({ length: 30 }, (_, i) => ({
  key: i,
  left: (i * 31 + 7) % 100,
  size: 2 + (i % 4),
  duration: 9 + (i % 9),
  delay: (i * 0.7) % 10,
  drift: ((i % 6) - 2.5) * 32,
}));

// Hexágonos flotantes que derivan y giran
const HEXES = Array.from({ length: 10 }, (_, i) => ({
  key: i,
  left: (i * 41 + 5) % 96,
  top: (i * 27 + 8) % 88,
  size: 46 + (i % 5) * 26,
  duration: 26 + (i % 7) * 4,
  delay: (i * 1.3) % 12,
  spin: i % 2 === 0 ? 'rwHexSpin' : 'rwHexSpinRev',
  faint: i % 3 === 0,
}));

// Destellos que titilan
const SPARKS = Array.from({ length: 28 }, (_, i) => ({
  key: i,
  left: (i * 47 + 3) % 100,
  top: (i * 59 + 11) % 96,
  size: 1 + (i % 3),
  duration: 3 + (i % 5),
  delay: (i * 0.8) % 7,
}));

/**
 * Fondo animado y decorado del sitio. Capas (de atrás hacia delante):
 * base + aurora en movimiento, resplandores, rejilla, hexágonos giratorios,
 * marca de agua del logo, brasas, destellos, barrido de luz y viñeta.
 * Se renderiza una sola vez (global) detrás de todo el contenido.
 */
export default function SiteBackground() {
  return (
    <div className="rw-bg" aria-hidden="true">
      <div className="rw-bg-base" />
      <div className="rw-bg-aurora" />
      <div className="rw-bg-glow rw-bg-glow--1" />
      <div className="rw-bg-glow rw-bg-glow--2" />
      <div className="rw-bg-glow rw-bg-glow--3" />
      <div className="rw-bg-grid" />

      <div className="rw-bg-hexes">
        {HEXES.map((h) => (
          <svg
            key={h.key}
            className={`rw-hex ${h.faint ? 'rw-hex--faint' : ''}`}
            viewBox="0 0 100 100"
            style={{
              left: `${h.left}%`,
              top: `${h.top}%`,
              width: h.size,
              height: h.size,
              animationDuration: `${h.duration}s, ${h.duration * 1.4}s`,
              animationDelay: `${h.delay}s, ${h.delay}s`,
              animationName: `rwHexFloat, ${h.spin}`,
            }}
          >
            <polygon points="50,3 93,26 93,74 50,97 7,74 7,26" />
          </svg>
        ))}
      </div>

      <img className="rw-bg-watermark" src={logoNuevo} alt="" />

      <div className="rw-bg-embers">
        {EMBERS.map((e) => (
          <span
            key={e.key}
            className="rw-ember"
            style={{
              left: `${e.left}%`,
              width: e.size,
              height: e.size,
              animationDuration: `${e.duration}s`,
              animationDelay: `${e.delay}s`,
              '--drift': `${e.drift}px`,
            }}
          />
        ))}
      </div>

      <div className="rw-bg-sparks">
        {SPARKS.map((s) => (
          <span
            key={s.key}
            className="rw-spark"
            style={{
              left: `${s.left}%`,
              top: `${s.top}%`,
              width: s.size,
              height: s.size,
              animationDuration: `${s.duration}s`,
              animationDelay: `${s.delay}s`,
            }}
          />
        ))}
      </div>

      <div className="rw-bg-sweep" />
      <div className="rw-bg-vignette" />
    </div>
  );
}
